// Three-axis bone rotation about a pivot. Order Z, Y, X - matching the
// engine transform convention. Accepts a scalar (X only, the original form)
// or { rx, ry, rz }.
function poseAngles(v) {
  if (v == null) return null;
  if (typeof v === "number") return { rx: v, ry: 0, rz: 0 };
  return { rx: v.rx || 0, ry: v.ry || 0, rz: v.rz || 0 };
}
function rotAboutAxes(p, pivot, a) {
  var x = p.x - pivot.x, y = p.y - pivot.y, z = p.z - pivot.z, c, s, nx, ny, nz;
  if (a.rz) { c = Math.cos(a.rz * DEG); s = Math.sin(a.rz * DEG);
    nx = x * c - y * s; ny = x * s + y * c; x = nx; y = ny; }
  if (a.ry) { c = Math.cos(a.ry * DEG); s = Math.sin(a.ry * DEG);
    nx = x * c + z * s; nz = -x * s + z * c; x = nx; z = nz; }
  if (a.rx) { c = Math.cos(a.rx * DEG); s = Math.sin(a.rx * DEG);
    ny = y * c - z * s; nz = y * s + z * c; y = ny; z = nz; }
  return v3(pivot.x + x, pivot.y + y, pivot.z + z);
}
// Walks a bone up its parent chain, applying each ancestor's rotation about
// that ancestor's pivot. Depth is capped so malformed data cannot loop.
function deformVert(p, g, partName, pose) {
  var vwt = 0;
  if (g.vw && p.__vi != null) vwt = g.vw[p.__vi] || 0;
  if (vwt > 0.02) {
    var jb = (scene.render && scene.render.jointBlend != null) ? scene.render.jointBlend : 1;
    vwt *= jb;
    if (vwt > 0.02) {
      var par = g.parts[partName] && g.parts[partName].parent;
      var full = deformChain(p, g, partName, pose);
      var soft = par ? deformChain(p, g, par, pose) : p;
      return v3(full.x + (soft.x - full.x) * vwt,
                full.y + (soft.y - full.y) * vwt,
                full.z + (soft.z - full.z) * vwt);
    }
  }
  return deformChain(p, g, partName, pose);
}
function deformChain(p, g, partName, pose) {
  var name = partName, depth = 0, out = p;
  while (name && depth < 8) {
    var part = g.parts[name];
    if (!part) break;
    var a = poseAngles(pose[name]);
    if (a && (a.rx || a.ry || a.rz)) out = rotAboutAxes(out, part.pivot, a);
    name = part.parent;
    depth++;
  }
  return out;
}

