  ctx.strokeStyle = "#2c2c2c"; ctx.lineWidth = 2; ctx.stroke();
  var red = card.s === 1 || card.s === 2;
  ctx.fillStyle = red ? "#c0392b" : "#1c1c1c";
  ctx.font = "bold " + Math.round(w * 0.34) + "px monospace";
  ctx.textAlign = "left"; ctx.textBaseline = "top";
  ctx.fillText(card.r, sx + w * 0.08, sy + h2 * 0.05);
  ctx.font = Math.round(w * 0.5) + "px monospace";
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillText(CARD_SUITS[card.s], sx + w / 2, sy + h2 * 0.58);
  ctx.restore();
