// ---- EXPLOSIONS ----
var EXPLOSIONS = [];
var DEBRIS = [];
function explode(ex, ey, ez, radius, force, damage) {
  radius = radius || 4; force = force || 9; damage = damage != null ? damage : 12;
  EXPLOSIONS.push({ x: ex, y: ey, z: ez, t: world.time, r: radius });
  playSound("__boom", { x: ex, z: ez });
  emit("spark", ex, ey + 0.4, ez, { scale: 2, jitter: 0.5 });
  emit("smoke", ex, ey + 0.5, ez, { scale: 2, jitter: 0.8 });
  decal(ex, ez, radius * 0.55, "#241a14", 25);
  var plx = nodes[playerId];
  if (plx && plx.worldPos) {
    var edist = Math.sqrt(Math.pow(plx.worldPos.x - ex, 2) + Math.pow(plx.worldPos.z - ez, 2));
    if (edist < radius * 3) camShake(0.8 * (1 - edist / (radius * 3)), 0.5);
  }
  var keys = Object.keys(nodes), ki, tn;
  for (ki = 0; ki < keys.length; ki++) {
    tn = nodes[keys[ki]];
    if (!tn.transform || tn._dead) continue;
    var edx = tn.transform.pos[0] - ex, edz = tn.transform.pos[2] - ez;
    var ed = Math.sqrt(edx * edx + edz * edz);
    if (ed > radius || ed < 1e-6) continue;
    var fall = 1 - ed / radius;
    if (tn.stats) {
      tn.hp = Math.max(0, (tn.hp || 0) - Math.round(damage * fall));
      tn._addPose = { id: "__stumble", t: 0 };
      if (POSED.indexOf(tn) < 0) POSED.push(tn);
      tn._deathImpulse = { x: edx / ed * force * fall, y: 3 * fall, z: edz / ed * force * fall };
